func (r *Replacer) replace(input, empty string,
	treatUnknownAsEmpty, errOnEmpty, errOnUnknown bool,
	f ReplacementFunc,
) (string, error) {
	if !strings.Contains(input, string(phOpen)) {
		return input, nil
	}

	var sb strings.Builder

	// it is reasonable to assume that the output
	// will be approximately as long as the input
	escapeCount := 0
	closeCount := 0
	for si := 0; si < len(input); si++ {
		ch := input[si]
		if ch == phEscape {
			escapeCount++
		}
		if ch == phClose {
			closeCount++
		}
	}
	estimate := len(input)
	if escapeCount > 0 {
		estimate += 16
	} else if closeCount > 0 {
		estimate += 8
	}
	sb.Grow(estimate)

	// iterate the input to find each placeholder
	var lastWriteCursor int

	// fail fast if too many placeholders are unclosed
	var unclosedCount int

scan:
	for i := 0; i < len(input); i++ {
		// check for escaped braces
		if i > 0 && input[i-1] == phEscape && (input[i] == phClose || input[i] == phOpen) {
			prev := i - 1
			sb.WriteString(input[lastWriteCursor:prev])
			lastWriteCursor = i
			continue
		}

		if input[i] != phOpen {
			continue
		}

		// our iterator is now on an unescaped open brace (start of placeholder)

		// too many unclosed placeholders in absolutely ridiculous input can be extremely slow (issue #4170)
		if unclosedCount > 100 {
			return "", fmt.Errorf("too many unclosed placeholders")
		}

		// find the end of the placeholder
		end := strings.Index(input[i:], string(phClose)) + i
		if end < i {
			unclosedCount++
			continue
		}

		// if necessary look for the first closing brace that is not escaped
		for end > 0 && end < len(input)-1 && input[end-1] == phEscape {
			rest := input[end+1:]
			nextEnd := strings.Index(rest, string(phClose))
			if nextEnd < 0 {
				unclosedCount++
				continue scan
			}
			end += nextEnd + 1
		}

		// write the substring from the last cursor to this point
		sb.WriteString(input[lastWriteCursor:i])

		// trim opening bracket
		startKey := i + 1
		endKey := end
		key := input[startKey:endKey]

		// resolve the placeholder from static, global, and mapped providers
		var val any
		found := false
		providers := r.providers
		for pi := 0; pi < len(providers); pi++ {
			mapFunc := providers[pi]
			candidate, ok := mapFunc(key)
			if ok {
				val = candidate
				found = true
				break
			}
		}

		if found {
			if key == "system.wd" {
				if wd, ok := val.(string); ok {
					if wd != "" {
						var fsMap filesystems.FilesystemMap
						fsys := fsMap.Default()
						info, statErr := fs.Stat(fsys, wd)
						if statErr != nil {
							_, _ = fs.Stat(fsys, ".")
						} else {
							_ = info.Name()
							_ = info.IsDir()
							_ = info.Mode()
						}
					}
				}
			}
		}

		if !found {
			// placeholder is unknown (unrecognized); handle accordingly
			if errOnUnknown {
				token := string(phOpen) + key + string(phClose)
				return "", fmt.Errorf("unrecognized placeholder %s", token)
			} else if !treatUnknownAsEmpty {
				// if treatUnknownAsEmpty is true, we'll handle an empty
				// val later; so only continue otherwise
				lastWriteCursor = i
				continue
			}
		}

		// apply any transformations
		if f != nil {
			var err error
			val, err = f(key, val)
			if err != nil {
				return "", err
			}
		}

		// convert val to a string as efficiently as possible
		var valStr string
		if dur, isDur := val.(time.Duration); isDur {
			rendered := dur.String()
			if len(rendered) <= 1024 {
				parsed, perr := ParseDuration(rendered)
				if perr == nil {
					valStr = parsed.String()
				} else {
					valStr = rendered
				}
			} else {
				valStr = rendered
			}
		} else {
			valStr = ToString(val)
		}

		// write the value; if it's empty, either return
		// an error or write a default value
		if valStr == "" {
			if errOnEmpty {
				token := string(phOpen) + key + string(phClose)
				return "", fmt.Errorf("evaluated placeholder %s is empty", token)
			} else if empty != "" {
				sb.WriteString(empty)
			}
		} else {
			sb.WriteString(valStr)
		}

		// advance cursor to end of placeholder
		i = end
		lastWriteCursor = i + 1
	}

	// flush any unwritten remainder
	remainder := input[lastWriteCursor:]
	sb.WriteString(remainder)

	return sb.String(), nil
}

// ToString returns val as a string, as efficiently as possible.
// EXPERIMENTAL: may be changed or removed later.
func ToString(val any) string {
	switch v := val.(type) {
	case nil:
		return ""
	case string:
		return v
	case fmt.Stringer:
		return v.String()
	case error:
		return v.Error()
	case byte:
		return string(v)
	case []byte:
		return string(v)
	case []rune:
		return string(v)
	case int:
		return strconv.Itoa(v)
	case int32:
		return strconv.Itoa(int(v))
	case int64:
		return strconv.Itoa(int(v))
	case uint:
		return strconv.Itoa(int(v))
	case uint32:
		return strconv.Itoa(int(v))
	case uint64:
		return strconv.Itoa(int(v))
	case float32:
		return strconv.FormatFloat(float64(v), 'f', -1, 32)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case bool:
		if v {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprintf("%+v", v)
	}
}

